const express = require('express');
const router = express.Router();
const { db } = require('../db');

router.put('/api/users/:userId/device-tokens/:tokenId/preferences', verifyToken, async (req, res) => {
  const { userId, tokenId } = req.params;
  const { marketingAlerts, transactionAlerts, soundEnabled } = req.body;

  if (req.user.id !== userId) {
    return res.status(403).json({ error: 'Forbidden: you cannot modify device preferences for other users' });
  }

  const result = await db.query(
    'UPDATE user_push_devices SET marketing_enabled = $1, transaction_enabled = $2, sound = $3 WHERE id = $4 AND user_id = $5 RETURNING *',
    [marketingAlerts, transactionAlerts, soundEnabled, tokenId, req.user.id]
  );

  if (result.rowCount === 0) return res.status(404).json({ error: 'Device token record not found' });
  return res.json({ success: true, preferences: result.rows[0] });
});
